import type { PoseTemplate } from '../types'

/*
 * Angles are segment directions in the mirror view the player sees:
 *   0 = up, 90 = toward the screen's right, ±180 = down, -90 = toward the screen's left.
 * The player's LEFT side is on the screen's LEFT. `length` < 1 marks a limb pointing at the camera.
 * Sided templates describe the LEFT variant; the right one is generated by mirroring.
 */

